      area:(occ: any, src: any, asof: any, base: any, net: any) =>`Чистий приріст площі: ${occ} км² окуповано за ${src} (${asof}) − ${base} км² окупованих до 24.02.2022 = ${net} км².`,
      alt:(src: any, net: any, v: any) =>`За картою ${src} приріст становить ${net} км², тоді — ≈ ${v} осіб на 1 км².`,
      caveat:'Грубий індикатор, а не точна «ціна». Втрати Генштаб ЗСУ заявляє сам, без незалежної перевірки, і вони включають втрати по всьому фронту, в обороні та від ударів, а не лише під час захоплення землі. Площа — чиста: з неї вже віднято звільнене Україною у 2022–2026 роках, тож захоплено загалом було більше. База до 2022 року — округлене зовнішнє значення, рахується в іншій проєкції, тому похибка — кілька відсотків.',
      method:'Як рахується',methodText:(d: any) =>`Особовий склад — накопичувальний підсумок Генштабу ЗСУ з поточного випуску. Техніка — підсумок Генштабу на ${d} плюс щоденний приріст з таймлайну втрат, тож цифра оновлюється з кожним випуском. Площа — шар «окуповано» DeepState з блоку карт (разом з Кримом і ОРДЛО), мінус площа, окупована до 24.02.2022. Оновлюється, коли оновлюється знімок карти.`,
